using System;using System.Collections.Generic;public class Solution{List<IList<int>>o=new();void F(int[]a,bool[]u,List<int>v){if(v.Count==a.Length){o.Add(new List<int>(v));return;}for(int i=0;i<a.Length;i++){if(u[i]||(i>0&&a[i]==a[i-1]&&!u[i-1]))continue;u[i]=true;v.Add(a[i]);F(a,u,v);v.RemoveAt(v.Count-1);u[i]=false;}}public IList<IList<int>> PermuteUnique(int[]a){Array.Sort(a);F(a,new bool[a.Length],new List<int>());return o;}}
